class Solution {
    unordered_map<string,string> raw,memo;
    string expand(string s) {
        string out;
        for(int i=0; i<(int)s.size(); ) {
            if(s[i]=='%') {
                int j=s.find('%',i+1);
                string key=s.substr(i+1,j-i-1);
                if(!memo.count(key))memo[key]=expand(raw[key]);
                out+=memo[key];
                i=j+1;
            }
            else out+=s[i++];
        }
        return out;
    }
    public:string applySubstitutions(vector<vector<string>>& replacements,string text) {
        for(auto &r:replacements)raw[r[0]]=r[1];
        return expand(text);
    }
}
